// Engine internals shared between engine modules (not for scripts).
#ifndef INTERNAL_H
#define INTERNAL_H

#include "engine.h"
#include "text.h"

#define MAX_ENTITIES 96
#define MAX_BODIES   8
#define CELL         16
#define SCREEN_W     240
#define SCREEN_H     160

// Generated by the exporter (assets.c)
extern const char game_title[];
extern const MenuSettings menu_settings;
extern const int boot_title;                // show the title menu at boot
extern const int show_frame_budget;         // always show the CPU meter
extern const int player_tag;                // the "Player" tag (0 = none), for saving the player's position
extern const Scene *const scenes[];
extern const int scene_count;
extern const int boot_scene;
extern const int var_count;

// main.c
extern u16 input_held, input_pressed, input_released;
extern int frame_counter;

// tilemap.c
void tilemap_load(const Scene *s);
void tilemap_draw(int camX, int camY);      // call in vblank
int tilemap_cell(int cx, int cy);
int tilemap_collision(int cx, int cy);      // COLL_*
int tilemap_tile_words(void);               // 32-bit words of tile graphics the tileset uses
extern int tilemap_w, tilemap_h;            // in cells

// entity.c
extern Entity entities[MAX_ENTITIES];
void entities_reset(void);
Entity *entity_spawn_template(const EntityTemplate *t, int x, int y, u16 id);
void entities_update(void);
void entities_render(int camX, int camY);   // fills the OAM shadow
void entities_commit(void);                 // in vblank: OAM + sprite frame uploads
void entities_flush_destroyed(void);

// sprite memory (entity.c)
int vram_alloc(int tiles);
void vram_free(int start, int tiles);
int pal_acquire(const SpriteAsset *s);
void pal_release(int bank);

// dialogue.c
void dialogue_update(void);
void dialogue_commit(void);                 // in vblank: canvas upload
void dialogue_render_portrait(u16 *oam);    // fills one OAM entry
void dialogue_reset(void);
bool dialogue_blocks_world(void);

// body.c
Body *body_alloc(const PlatformerSettings *s, u8 flags);
void body_free(Body *b);
void body_reset_all(void);
void body_step(Entity *e);

// camera.c
void camera_reset(const Scene *s, Entity *target);
void camera_update(void);
bool camera_paused_world(void);             // during screen slides the world freezes
extern int cam_x, cam_y;                    // top-left of the view in px (after shake)

// background.c
void background_commit(void);               // in vblank
void background_reset(void);                // after the tileset is loaded

// sound.c
void sound_init(void);
void sound_commit(void);                    // in vblank
void sound_update(void);                    // once per frame: mix the next buffer

// save.c
void save_init(void);
bool save_apply_pending(void);              // end of frame: load a saved game

// menu.c
void menu_boot(void);                       // open the title menu
bool menu_update(void);                     // after input: true = keep the world frozen
void menu_apply_pending(void);              // end of frame

// draw.c
void draw_begin(void);                      // before scripts run: forget last frame's lines
void draw_render(int camX, int camY);       // rasterize this frame's lines
void draw_commit(void);                     // in vblank
void draw_reset(void);

// main.c (scenes)
void scene_apply_pending(void);
void scene_start(int index);
extern const Scene *scene_current;

#endif
